(1, '2020', '76.01', '1.03.0.00.0.00.01.0000', '02 TAHUN 2020', '2020-01-03', 'Pengangkatan Pejabat Pembuat Komitmen (PPK) Konstruksi Dan  Pengangkatan Pejabat Pembuat Komitmen (PPK) Konsultansi Dinas Pekerjaan Umum Dan Penataan Ruang Kabupaten Pasangkayu Tahun 2020', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198006152006041018\", \"nama\": \"Sumarlin, ST\", \"jabatan\": \"Sekretaris Dinas\", \"pangkat\": \"Pembina , IV/a\", \"jabatan_sk\": \"PPK Cipta Karya dan Sekretariat\"}, \"1\": {\"nip\": \"197308142005021003\", \"nama\": \"Kamaruddin, ST\", \"jabatan\": \"Kepala Bidang Pembinaan Jasa Konstruksi\", \"pangkat\": \"Pembina , IV/a\", \"jabatan_sk\": \"PPK Pembinaan Jasa Konstruksi\"}, \"2\": {\"nip\": \"197101152007011019\", \"nama\": \"Herry Hasanuddin. M, ST\", \"jabatan\": \"Kepala Bidang Penataan Ruang\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"PPK Penataan Ruang\"}, \"3\": {\"nip\": \"197501192007011013\", \"nama\": \"Muammar Nur, ST\", \"jabatan\": \"Kepala Bidang Binamarga\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"PPK Binamarga\"}, \"4\": {\"nip\": \"197908252009031003\", \"nama\": \"Pusmahasib, S.Si\", \"jabatan\": \"Plt. Kepala Bidang Sumber Daya Air\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPK Sumber Daya Air\"}}', 0, '{\"0\": {\"isi\": \"Bahwa untuk pelaksanaan proses kerja pengadaan barang / jasa pemerintah yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pembuat Komitmen (PPK) pada Dinas Pekerjaan Umum Kabupaten Pasangkayu\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581)\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63)\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270)\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286)\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355)\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548)\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi\"}, \"8\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5)\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah\"}, \"13\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020\"}, \"14\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020\"}}', '{\"0\": {\"isi\": \"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"menyusun perencanaan pengadaan\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"menetapkan spesifikasi teknis/Kerangka Acuan Kerja (KAK)\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"menetapkan rancangan kontrak\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"menetapkan HPS\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"menetapkan besaran uang muka yang akan dibayarkan kepada Penyedia\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"mengusulkan perubahan jadwal kegiatan\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"menetapkan tim pendukung\", \"p_l\": \"L\"}, \"8\": {\"isi\": \"menetapkan tim atau tenaga ahli\", \"p_l\": \"L\"}, \"9\": {\"isi\": \"melaksanakan E-purchasing untuk nilai paling sedikit di atas Rp200.000.000,00 (dua ratus juta rupiah)\", \"p_l\": \"L\"}, \"10\": {\"isi\": \"menetapkan Surat Penunjukan Penyedia Barang/Jasa\", \"p_l\": \"L\"}, \"11\": {\"isi\": \"mengendalikan Kontrak\", \"p_l\": \"L\"}, \"12\": {\"isi\": \"melaporkan pelaksanaan dan penyelesaian kegiatan kepada PA/KPA\", \"p_l\": \"L\"}, \"13\": {\"isi\": \"menyerahkan hasil pekerjaan pelaksanaan kegiatan kepada PA/KPA dengan berita acara penyerahan\", \"p_l\": \"L\"}, \"14\": {\"isi\": \"menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan kegiatan\", \"p_l\": \"L\"}, \"15\": {\"isi\": \"menilai kinerja Penyedia\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Selain tugas pokok dan kewenangan sebagaimana dimaksud, dalam hal diperlukan, PPK,dapat\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"melakukan tindakan yang mengakibatkan pengeluaran anggaran belanja\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"mengadakan dan menetapkan perjanjian dengan pihak lain dalam batas anggaran belanja yang telah ditetapkan\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"PPK dalam melaksanakan tugas sebagaimana dimaksud dapat dibantu oleh Pengelola Pengadaan Barang/Jasa\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melaporkan kemajuan pekerjaan termasuk penyerapan anggaran dan hambatan pelaksanaan pekerjaan kepada PA/KPA setiap triwulan\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan Pengadaan barang/Jasa Pemerintah\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(3, '2020', '76.01', '1.03.0.00.0.00.01.0000', '06 TAHUN 2020', '2020-01-03', 'pengangkatan pejabat pengadaan barang / jasa pemerintah pada dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198404262011011011\", \"nama\": \"I Ketut Suriyana, ST\", \"jabatan\": \"Kasie Air Minum\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Cipta Karya\"}, \"1\": {\"nip\": \"197507272010011004\", \"nama\": \"Rajamang, ST\", \"jabatan\": \"Kasie Irigasi\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Sumber Daya Air\"}, \"2\": {\"nip\": \"198007112006041010\", \"nama\": \"Alwi Mansyur, A.Md\", \"jabatan\": \"Plt. kasubag program\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Binamarga/Sekretariat dan Pembinaan Jasa Konstruksi\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja pengelolaan Barang / Jasa yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pengadaan Barang / Jasa pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581)\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63)\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270)\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286)\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355)\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548)\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi\"}, \"8\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5)\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah\"}, \"13\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020\"}, \"14\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020\"}}', '{\"0\": {\"isi\": \"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Pengadaan Langsung;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Barang/Pekerjaan Konstruksi/Jasa Lainnya yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Jasa Konsultansi yang bernilai paling banyak Rp100.000.000,00 (seratus juta rupiah);\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"melaksanakan E-purchasing yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Menyerahkan dokumen asli pemilihan penyedia barang / jasa Pemerintah kepada pengguna anggaran;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Membuat laporan mengenai proses dan hasil pengadaan kepada pengguna anggaran; dan\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"Memberikan pertanggungjawaban atas pelaksanaan kegiatan pengadaan barang / jasa Konstruksi kepada pengguna anggaran\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepadaÂ Pos AnggaranÂ Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(4, '0000', '76.01', '1.03.0.00.0.00.01.0000', '03  TAHUN 2020', '2020-01-03', 'pengangkatan pejabat penatausahaan keuangan  dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198407252009031001\", \"nama\": \"Felix Datuan, ST\", \"jabatan\": \"Kepala Sub Bagian Keuangan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Pejabat Penatausahaan Keuangan\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk menyediakan pengelolaan keuangan Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Penatausahaan Keuangan pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"}, \"5\": {\"isi\": \"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"}, \"8\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"9\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"}, \"10\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Meneliti Kelengkapan SPP-LS pengadaan barang dan jasa yang disampaikan oleh bendahara pengeluaran dan diketahui/disetujui oleh PPTK;\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Meneliti kelengkapan SPP-UP, SPP-GU dan SPP-LS gaji dan tunjangan PNS serta penghasilan lainnya yang ditetapkan sesuai dengan ketentuan perundang-undangan yang diajukan oleh bendahara pengeluaran;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan Verifikasi SPP;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Menyiapkan SPM;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melakukan verifikasi harian atas penerimaan;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Melaksanakan akuntansi SKPD; dan\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Menyiapkan laporan keuangan SKPD.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu;\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan;\"}, \"5\": {\"tembusan\": \"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(5, '0000', '76.01', '1.03.0.00.0.00.01.0000', '04  TAHUN 2020', '2020-01-03', 'pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dan tim teknis dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198208022003122003\", \"nama\": \"Nurmadina, S.Sos.M.Si\", \"jabatan\": \"kasie bina teknik dan kelembagaan jasa konstruksi\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Bina Teknik dan Kelembagaan Jasa Konstruksi\"}, \"1\": {\"nip\": \"198712042011012008\", \"nama\": \"Hasmia, S.Sos\", \"jabatan\": \"kasie pengaturan dan pengawasan jasa konstruksi\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Pengaturan dan Pengawasan Jasa Konstruksi\"}, \"2\": {\"nip\": \"198410152010011003\", \"nama\": \"Hamka, SH\", \"jabatan\": \"kasie pemberdayaan jasa konstruksi\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"PPTK/Tim Teknis Pemberdayaan Jasa Konstruksi\"}, \"3\": {\"nip\": \"197511282011011002\", \"nama\": \"Muh. Hirman Madjid, ST\", \"jabatan\": \"kasie bangunan gedung dan lingkungan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Bangunan Gedung dan Lingkungan\"}, \"4\": {\"nip\": \"198406172009032002\", \"nama\": \"Rahmania, ST\", \"jabatan\": \"kasie sanitasi dan penyehatan lingkungan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Sanitasi dan Penyehatan Lingkungan\"}, \"5\": {\"nip\": \"198404262011011011\", \"nama\": \"I Ketut Suriyana, ST\", \"jabatan\": \"kasie air minum\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Air Minum\"}, \"6\": {\"nip\": \"198301012010011020\", \"nama\": \"I Nyoman Sumerta, ST\", \"jabatan\": \"kasie pembangunan jalan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Pembangunan Jalan\"}, \"7\": {\"nip\": \"197910012011011004\", \"nama\": \"Nardin, ST\", \"jabatan\": \"kasie pembangunan jembatan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Pembangunan Jembatan\"}, \"8\": {\"nip\": \"197110122009031001\", \"nama\": \"Patahuddin, ST\", \"jabatan\": \"kasie pemeliharaan jalan,jembatan dan peralatan\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"PPTK/Tim Teknis Pemeliharaan Jalan, Jembatan dan Peralatan\"}, \"9\": {\"nip\": \"197507272010011004\", \"nama\": \"Rajamang, ST\", \"jabatan\": \"kasie irigasi\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Irigasi\"}, \"10\": {\"nip\": \"198012062009031001\", \"nama\": \"Syahruddin, ST\", \"jabatan\": \"kasie pengendalian dan pelestarian sumber daya air\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"PPTK/Tim Teknis Pengendalian dan Pelestarian SDA\"}, \"11\": {\"nip\": \"198308082012121002\", \"nama\": \"Fuady Kahar, SH\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"PPTK Sekretariat\"}, \"12\": {\"nip\": \"198001282012122003\", \"nama\": \"Suriyana, ST\", \"jabatan\": \"kasie perencanaan ruang\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"PPTK/Tim Teknis Bidang Penataan Ruang\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja Pengadaan Barang / Jasa Pemerintah yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pelaksana Teknis Kegiatan (PPTK) dan tim teknis pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2020;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Mengendalikan pelaksanaan kegiatan;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melaporkan perkembangan pelaksanaan kegiatan;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Menyiapkan dokumen anggaran atas beban pengeluaran pelaksanaan kegiatan;dan\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Membantu Pejabat Pembuat Komitmen dalam melaksanakan tugasnya.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', 