(13, '0000', '76.01', '1.03.0.00.0.00.01.0000', '17  TAHUN 2020', '2020-01-03', 'pengangkatan pejabat pembantu pengurus barang pengguna dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198510092014091002\", \"nama\": \"Agussalim T\", \"jabatan\": \"STAF\", \"pangkat\": \"Pengatur Muda, II/a\", \"jabatan_sk\": \"Pembantu Pengurus Barang Pengguna\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja pengelolaan asset dan barang, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Paasangkayu, maka dipandang perlu mengangkat pembantu pengurus Â barang pengguna pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2020;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"membantu menyiapkan dokumen rencana kebutuhan dan penganggaran barang milik daerah;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"menyiapkan usulan permohonan penetapan status penggunaan barang milik daerah yang diperoleh dari beban APBD dan perolehan lainnya yang sah;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"melaksanakan pencatatan dan inventarisasi barang milik daerah;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"membantu mengamankan barang milik daerah yang berada pada Pengguna Barang;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"menyiapkan dokumen pengajuan usulan pemanfaatan dan pemindahtanganan barang milik daerah berupa tanah dan/atau bangunan yang tidak memerlukan persetujuan DPRD dan barang milik daerah selain tanah dan/atau bangunan;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"menyiapkan dokumen penyerahan barang milik daerah berupa tanah dan/atau bangunan yang tidak digunakan untuk kepentingan penyelenggaraan tugas dan fungsi Pengguna Barang dan sedang tidak dimanfaatkan pihak lain;\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"menyiapkan dokumen pengajuan usulan pemusnahan dan penghapusan barang milik daerah;\", \"p_l\": \"L\"}, \"8\": {\"isi\": \"menyusun laporan barang semesteran dan tahunan;\", \"p_l\": \"L\"}, \"9\": {\"isi\": \"menyiapkan Surat Permintaan Barang (SPB) berdasarkan nota permintaan barang;\", \"p_l\": \"L\"}, \"10\": {\"isi\": \"mengajukan Surat Permintaan Barang (SPB) kepada Pejabat Penatausahaan Barang Pengguna;\", \"p_l\": \"L\"}, \"11\": {\"isi\": \"menyerahkan barang berdasarkan Surat Perintah Penyaluran Barang (SPPB) yang dituangkan dalam berita acara penyerahan barang;\", \"p_l\": \"L\"}, \"12\": {\"isi\": \"membuat Kartu Inventaris Ruangan (KIR) semesteran dan tahunan;\", \"p_l\": \"L\"}, \"13\": {\"isi\": \"memberi label barang milik daerah;\", \"p_l\": \"L\"}, \"14\": {\"isi\": \"mengajukan permohonan persetujuan kepada Pejabat Penatausahaan Pengguna Barang atas perubahan kondisi fisik barang milik daerah berdasarkan pengecekan fisik barang;\", \"p_l\": \"L\"}, \"15\": {\"isi\": \"melakukan stock opname barang persediaan;\", \"p_l\": \"L\"}, \"16\": {\"isi\": \"menyimpan dokumen, antara lain: fotokopi/salinan dokumen kepemilikan barang milik daerah dan menyimpan asli/fotokopi/salinan dokumen penatausahaan;\", \"p_l\": \"L\"}, \"17\": {\"isi\": \"melakukan rekonsiliasi dalam rangka penyusunan laporan barang Pengguna Barang dan laporan barang milik daerah;\", \"p_l\": \"L\"}, \"18\": {\"isi\": \"membuat laporan mutasi barang setiap bulan yang disampaikan kepada Pengelola Barang melalui Pengguna Barang setelah diteliti oleh Pejabat Penatausahaan Pengguna Barang.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(14, '0000', '76.01', '1.03.0.00.0.00.01.0000', '19  TAHUN 2020', '2020-03-02', 'perubahan penetapan administrator keuangan dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198007112006041010\", \"nama\": \"Alwi Mansyur, A.Md\", \"jabatan\": \"Plt. kasubag program\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Administrator Keuangan\"}, \"1\": {\"nip\": \"198509192010012002\", \"nama\": \"Santi, SE\", \"jabatan\": \"STAF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Administrator Keuangan\"}, \"2\": {\"nip\": \"198502112015031004\", \"nama\": \"Dirgantara, ST\", \"jabatan\": \"STAF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Administrator Keuangan\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja pengelolaan keuangan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Administrator Keuangan pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"}, \"5\": {\"isi\": \"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"}, \"8\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"9\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"}, \"10\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Membantu Kegiatan Sekretariat bagian penyusunan program dan keuangan;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Membantu mempersiapkan dokumen perencanaan opd;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Membantu Bendahara Pengeluaran;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Mempersiapkan /Membuat dan Meneliti Dokumen SPP;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Menatausahakan keuangan daerah;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Melaporkan hasil administrasi keuangan secara berkala.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Mencabut surat keputusan Nomor 10 Tahun 2020 tertanggal 3 Januari 2020 tentang penetapan Administrator Kantor Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu Tahun 2020, dinyatakan Tidak berlaku.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu;\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan;\"}, \"5\": {\"tembusan\": \"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0);
