(64, '0000', '76.01', '1.03.0.00.0.00.01.0000', '10.a TAHUN 2022', '2022-09-01', 'penetapan administrator keuangan dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Alwi Mansyur, A.Md\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198007112006041010\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"},\"1\":{\"nama\":\"Abdul Haris Rustam, A.Md\",\"pangkat\":\"Penata Muda, III/a\",\"nip\":\"199908212019031010\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"},\"2\":{\"nama\":\"Rachmiy. S\",\"pangkat\":\"Pengatur Muda Tingkat I, II/b\",\"nip\":\"197709302012122002\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan keuangan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Administrator Keuangan pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"},\"5\":{\"isi\":\"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Membantu Kegiatan Sekretariat bagian penyusunan program dan keuangan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Membantu mempersiapkan dokumen perencanaan opd;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membantu Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Mempersiapkan /Membuat dan Meneliti Dokumen SPP;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menatausahakan keuangan daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Melaporkan hasil administrasi keuangan secara berkala.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Dengan terbitnya Surat Keputusan ini maka SK Nomor 10 Tahun 2022 tentang penetapan administrator keuangan dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022, dinyatakan tidak berlaku lagi.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu;\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan;\"},\"5\":{\"tembusan\":\"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
