(73, '2023', '76.01', '1.03.0.00.0.00.01.0000', '11 TAHUN 2023', '2023-01-11', 'pengangkatan sopir kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"M. IRWAN\",\"pangkat\":\"Non ASN\",\"nip\":\"Non ASN\",\"jabatan\":\"Honorer\",\"jabatan_sk\":\"Sopir Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk kelancaran pelaksanaan perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat sopir pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud penetapan adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Memeriksa kelengkapan kendaraan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Mengantarkan pimpinan dalam melaksanakan tugas sesuai dengan perintah;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membersihkan Mobil/kendaraan dinas;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melakukan service dan penggantian suku cadang yang sudah rusak dibengkel;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(74, '2023', '76.01', '1.03.0.00.0.00.01.0000', '10 TAHUN 2023', '2023-01-11', 'penetapan administrator keuangan/Staf Pengelola dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Alwi Mansyur, A.Md\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198007112006041010\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Staf Pengelola/Administrator Keuangan\"},\"1\":{\"nama\":\"Santi, SE\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198509192010012002\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Staf Pengelola/Administrator Keuangan\"},\"2\":{\"nama\":\"Lelianti\",\"pangkat\":\"Pengatur II/c\",\"nip\":\"197712242012122001\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Staf Pengelola/Administrator Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan keuangan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Administrator Keuangan pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"},\"5\":{\"isi\":\"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Membantu Kegiatan Sekretariat bagian penyusunan program dan keuangan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Membantu mempersiapkan dokumen perencanaan opd;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membantu Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Mempersiapkan /Membuat dan Meneliti Dokumen SPP;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menatausahakan keuangan daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Melaporkan hasil administrasi keuangan secara berkala.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu;\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan;\"},\"5\":{\"tembusan\":\"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(75, '2023', '76.01', '1.03.0.00.0.00.01.0000', '25 TAHUN 2023', '2023-03-16', 'perubahan pengangkatan pejabat penatausahaan keuangan  dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Mahmud, SP., M.Si\",\"pangkat\":\"Pembina Tingkat I, IV/b\",\"nip\":\"196901272002121004\",\"jabatan\":\"sekretaris dinas\",\"jabatan_sk\":\"Pejabat Penatausahaan Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk menyediakan pengelolaan keuangan Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Penatausahaan Keuangan pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"},\"5\":{\"isi\":\"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"PPK SKPD mempunyai tugas dan wewenang:\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melakukan verifikasi SPP-UP, SPP-GU, SPP-TU, dan SPP-LS beserta bukti kelengkapannya yang diajukan oleh Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan SPM;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melakukan verifikasi laporan pertanggungjawaban Bendahara Penerimaan dan Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"melaksanakan fungsi akuntansi pada SKPD; dan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"menyusun laporan keuangan SKPD.\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Verifikasi oleh PPK SKPD dilakukan dengan tujuan untuk meneliti kelengkapan dan keabsahan.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Selain melaksanakan tugas dan wewenang pada angka 5, PPK SKPD melaksanakan tugas dan wewenang lainnya yaitu:\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melakukan verifikasi SPP-UP, SPP-GU, SPP-TU, dan SPP-LS beserta bukti kelengkapannya yang diajukan oleh Bendahara lainnya;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"melakukan verifikasi surat permintaan pembayaran atas pengembalian kelebihan pendapatan daerah dari bendahara penerimaan; dan\",\"p_l\":\"L\"},\"3\":{\"isi\":\"menerbitkan surat pernyataan verifikasi kelengkapan dan keabsahan SPP-UP, SPP-GU, SPP-TU dan SPP-LS beserta bukti kelengkapannya sebagai dasar penyiapan SPM.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Dengan terbitnya Surat Keputusan ini maka SK Nomor 3 Tahun 2023 tentang pengangkatan pejabat penatausahaan keuangan dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023, dinyatakan tidak berlaku lagi.\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu;\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan;\"},\"5\":{\"tembusan\":\"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
