(117, '2025', '76.01', '1.03.0.00.0.00.01.0000', '60 TAHUN 2025', '2025-09-30', 'perubahan pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025', '197503102009031001', 'Kepala', 'Pembina, IV/a', 'SYAMSUNAR, SP.,M.M', '[{\"nama\":\"Kamaruddin, ST\",\"pangkat\":\"Pembina , IV\\/a\",\"nip\":\"197308142005021003\",\"jabatan\":\"Kepala Bidang Pembinaan Jasa Konstruksi\",\"jabatan_sk\":\"PPTK Bidang Pembinaan Jasa Konstruksi Dan Penataan Dan Pemanfaatan Ruang\"},{\"nama\":\"Bachtiar,&nbsp;\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"197503102009031001\",\"jabatan\":\"Kepala bidang bina marga\",\"jabatan_sk\":\"PPTK Bidang Bina Marga dan Peralatan alat Laboratorium\\/Alat Berat\"},{\"nama\":\"I Nyoman Sumerta, ST\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"198301012010011020\",\"jabatan\":\"Kepala bidang sumber daya air\",\"jabatan_sk\":\"PPTK Bidang Sumber Daya Air\"},{\"nama\":\"Nardin, ST\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"197910012011011004\",\"jabatan\":\"Kepala bidang cipta karya\",\"jabatan_sk\":\"PPTK Bidang Cipta Karya\"},{\"nama\":\"Irmawati, SE\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"197601032006042007\",\"jabatan\":\"Kasubag umum dan kepegawaian\",\"jabatan_sk\":\"PPTK Sekretariat\"},{\"nama\":\"Rahmania, ST.MT\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"198406172009032002\",\"jabatan\":\"Tehnik penyehatan lingkungan\",\"jabatan_sk\":\"PPTK&nbsp;UPTD Air Minum dan UPTD Pengolahan Air Limbah\"}]', 1, '[{\"isi\":\"bahwa untuk pelaksanaan proses kerja Pengadaan Barang \\/ Jasa Pemerintah dan kelancaran sub kegiatan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pelaksana Teknis Kegiatan (PPTK) pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2025;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"},{\"isi\":\"\",\"p_l\":\"P\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Pemerintah Nomor 12 Tahun 2019 tentang Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2024 tanggal 31 Desember 2024 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 39 Tahun 2024 tanggal 31 Desember 2024 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"14\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2021 tanggal 30 Desember 2021 tentang Kedudukan, Susunan Organisasi, Tugas dan Fungsi serta Tata Kerja Perangkat Daerah.<br>\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas PPTK dalam membantu tugas dan wewenang PA\\/ KPA sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"mengendalikan dan melaporkan perkembangan pelaksanaan teknis Kegiatan\\/sub kegiatan SKPD\\/Unit SKPD;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan dokumen dalam rangka pelaksanaan anggaran atas Beban pengeluaran pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"menyiapkan dokumen pengadaan barang\\/jasa pada Kegiatan\\/Sub kegiatan SKPD\\/Unit SKPD sesuai ketentuan peraturan perundang-undangan yang mengatur mengenai pengadaan barang\\/jasa.\",\"p_l\":\"L\"},\"4\":{\"isi\":\"<div>Tugas mengendalikan dan melaporkan pelaksanaan teknis&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">Kegiatan\\/Sub kegiatan meliputi:<\\/span><\\/div>\",\"p_l\":\"P\"},\"5\":{\"isi\":\"menyusun jadwal pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"<div>memonitoring dan evaluasi pelaksanaan Kegiatan\\/Sub kegiatan;&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">dan<\\/span><\\/div>\",\"p_l\":\"L\"},\"7\":{\"isi\":\"<div>melaporkan perkembangan pelaksanaan Kegiatan\\/Sub kegiatan&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">kepada PA\\/KPA.<\\/span><\\/div>\",\"p_l\":\"L\"},\"8\":{\"isi\":\"<div>Tugas menyiapkan dokumen dalam rangka pelaksanaan anggaran atas&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">beban pengeluaran pelaksanaan Kegiatan\\/Sub kegiatan meliputi:<\\/span><\\/div>\",\"p_l\":\"P\"},\"9\":{\"isi\":\"menyiapkan laporan kinerja pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"<div>menyiapkan dokumen administrasi pembayaran sesuai dengan&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">persyaratan yang ditetapkan dalam ketentuan perundang-<\\/span><span style=\\\"text-align: inherit; font-size: 1em;\\\">undangan; dan<\\/span><\\/div>\",\"p_l\":\"L\"},\"11\":{\"isi\":\"<div>menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">kegiatan.<\\/span><\\/div>\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2025.\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Dengan berlakunya Surat Keputusan ini maka Surat Keputusan Nomor 03 Tahun 2025 tentang pengangkatan&nbsp; pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025&nbsp; dicabut dan tidak berlaku lagi.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah 